try {
  var items = $input.all();
  var stdout = items[0].json.stdout || '{}';

  console.log('VAD stdout (first 300 chars): ' + stdout.substring(0, 300));

  // Extract the last JSON object from stdout (Whisper/VAD may print progress to stdout)
  var jsonMatch = stdout.match(/\{[^{}]*"speech_segments"[\s\S]*\}/);
  if (!jsonMatch) {
    throw new Error('No JSON found in silence detection output. stdout: ' + stdout.substring(0, 500));
  }

  var vadResults = JSON.parse(jsonMatch[0]);

  if (vadResults.error) {
    throw new Error('Silence detection script error: ' + vadResults.error);
  }

  var speechSegments = vadResults.speech_segments || [];
  var inputVideoPath = $('Set Variables').item.json.inputVideoPath;
  var outputFolder = $('Set Variables').item.json.outputFolder;
  var silenceRemovedPath = outputFolder + '/silence_removed.mp4';

  console.log('Speech segments count: ' + speechSegments.length);

  var command;

  if (speechSegments.length === 0) {
    // No speech — copy as-is
    console.log('No speech segments found, copying input file');
    command = 'cp "' + inputVideoPath + '" "' + silenceRemovedPath + '"';
  } else {
    // Build FFmpeg filter_complex to keep only speech segments
    var filterParts = [];
    var vStreams = '';
    var aStreams = '';
    var n = speechSegments.length;

    for (var i = 0; i < n; i++) {
      var seg = speechSegments[i];
      filterParts.push('[0:v]trim=start=' + seg.start.toFixed(3) + ':end=' + seg.end.toFixed(3) + ',setpts=PTS-STARTPTS[v' + i + ']');
      filterParts.push('[0:a]atrim=start=' + seg.start.toFixed(3) + ':end=' + seg.end.toFixed(3) + ',asetpts=PTS-STARTPTS[a' + i + ']');
      vStreams += '[v' + i + ']';
      aStreams += '[a' + i + ']';
    }

    filterParts.push(vStreams + 'concat=n=' + n + ':v=1:a=0[outv]');
    filterParts.push(aStreams + 'concat=n=' + n + ':v=0:a=1[outa]');

    var filterComplex = filterParts.join(';');
    console.log('filter_complex segments: ' + n);

    command = 'ffmpeg -i "' + inputVideoPath + '" -filter_complex "' + filterComplex + '" -map "[outv]" -map "[outa]" -c:v libx264 -preset fast -crf 18 -c:a aac -b:a 192k "' + silenceRemovedPath + '" -y 2>&1';
  }

  return [{
    json: {
      command: command,
      silenceRemovedPath: silenceRemovedPath,
      outputFolder: outputFolder,
      inputVideoPath: inputVideoPath,
      segmentCount: speechSegments.length
    }
  }];

} catch (e) {
  console.log('Error in Process VAD Results: ' + e.message);
  throw new Error('VAD processing failed: ' + e.message);
}

try {
  var items = $input.all();
  var stdout = items[0].json.stdout || '{}';

  console.log('Trigger detection stdout (first 300 chars): ' + stdout.substring(0, 300));

  var jsonMatch = stdout.match(/\{[^{}]*"cut_segments"[\s\S]*\}/);
  if (!jsonMatch) {
    throw new Error('No JSON found in trigger detection output. stdout: ' + stdout.substring(0, 500));
  }

  var detectionResults = JSON.parse(jsonMatch[0]);

  if (detectionResults.error) {
    throw new Error('Trigger detection script error: ' + detectionResults.error);
  }

  var cutSegments = detectionResults.cut_segments || [];
  var duration = detectionResults.duration || 0;
  var outputFolder = $('Set Variables').item.json.outputFolder;
  var silenceRemovedPath = $('Process VAD Results').item.json.silenceRemovedPath;
  var mistakesRemovedPath = outputFolder + '/mistakes_removed.mp4';

  console.log('Segments to cut: ' + cutSegments.length);

  var command;

  if (cutSegments.length === 0) {
    console.log('No trigger words found, copying file');
    command = 'cp "' + silenceRemovedPath + '" "' + mistakesRemovedPath + '"';
  } else {
    // Build keep segments (everything NOT in cut_segments)
    var keepSegments = [];
    var prevEnd = 0.0;

    for (var i = 0; i < cutSegments.length; i++) {
      var cut = cutSegments[i];
      if (prevEnd < cut.start - 0.001) {
        keepSegments.push({ start: prevEnd, end: cut.start });
      }
      prevEnd = cut.end;
    }

    // Keep everything after the last cut
    if (duration > 0 && prevEnd < duration - 0.1) {
      keepSegments.push({ start: prevEnd, end: duration });
    } else if (duration === 0) {
      // Duration unknown — trim to a large number (FFmpeg will stop at EOF)
      keepSegments.push({ start: prevEnd, end: 99999.0 });
    }

    if (keepSegments.length === 0) {
      throw new Error('No keep segments remain after cutting — entire video would be deleted');
    }

    var filterParts = [];
    var vStreams = '';
    var aStreams = '';
    var n = keepSegments.length;

    for (var j = 0; j < n; j++) {
      var seg = keepSegments[j];
      filterParts.push('[0:v]trim=start=' + seg.start.toFixed(3) + ':end=' + seg.end.toFixed(3) + ',setpts=PTS-STARTPTS[v' + j + ']');
      filterParts.push('[0:a]atrim=start=' + seg.start.toFixed(3) + ':end=' + seg.end.toFixed(3) + ',asetpts=PTS-STARTPTS[a' + j + ']');
      vStreams += '[v' + j + ']';
      aStreams += '[a' + j + ']';
    }

    filterParts.push(vStreams + 'concat=n=' + n + ':v=1:a=0[outv]');
    filterParts.push(aStreams + 'concat=n=' + n + ':v=0:a=1[outa]');

    var filterComplex = filterParts.join(';');
    console.log('Generated keep filter_complex with ' + n + ' segments');

    command = 'ffmpeg -i "' + silenceRemovedPath + '" -filter_complex "' + filterComplex + '" -map "[outv]" -map "[outa]" -c:v libx264 -preset fast -crf 18 -c:a aac -b:a 192k "' + mistakesRemovedPath + '" -y 2>&1';
  }

  return [{
    json: {
      command: command,
      mistakesRemovedPath: mistakesRemovedPath,
      outputFolder: outputFolder
    }
  }];

} catch (e) {
  console.log('Error in Process Cut Points: ' + e.message);
  throw new Error('Cut point processing failed: ' + e.message);
}
